INSERT INTO public.journal_entries VALUES ('faaf4551-366e-4199-88a8-50138eaf169b', '8a15f3b4-35a3-4810-beb5-85c298d0633b', 'Almost done the course.', 'great', 6, 7, '2025-12-11 20:49:34.362053');
INSERT INTO public.suggestions VALUES ('b7d866de-9ba9-454f-8c19-c0c94e8c4e57', 1, 1, 'Notice Your Breathing', 'Take 5 minutes today to gently observe how you breathe when you''re around other people. There''s no need to change anything - simply notice if your breathing becomes shallow or speeds up. This gentle awareness is the first step in your journey.', 'awareness');
INSERT INTO public.suggestions VALUES ('b94a76ec-7d46-4e55-bb82-3db917e34f51', 1, 2, 'Body Scan Check-in', 'Before you enter any social space today, take a moment to check in with your body. Notice where you might be holding tension - your shoulders, jaw, or stomach - and gently allow those areas to soften and relax.', 'awareness');
INSERT INTO public.suggestions VALUES ('cb902bdc-0160-480d-9b14-248d140e5936', 1, 3, 'Thought Observation', 'Today, gently capture 3 thoughts that come up before you interact with others. There''s no need to judge or change these thoughts - simply notice them and see if you can spot any patterns emerging.', 'awareness');
INSERT INTO public.suggestions VALUES ('65fcd2a2-b873-4b24-90c5-e7b455d3ce8d', 1, 4, 'Comfort Zone Mapping', 'Take some time today to map out your social comfort zone. You might draw it or make a list - whatever feels natural. Notice which social situations feel easy and welcoming, and which ones feel more challenging right now.', 'awareness');
INSERT INTO public.suggestions VALUES ('ab0067f7-4b53-41ca-9694-a0b194502267', 1, 5, 'Anxiety Trigger Journal', 'Carry a small notebook with you today and gently note any specific moments or situations that trigger feelings of social anxiety. This isn''t about fixing anything - just building awareness of your unique patterns.', 'awareness');
INSERT INTO public.suggestions VALUES ('7098f5fb-ddd5-474c-a792-f0a9a954c5e2', 1, 6, 'Self-Compassion Practice', 'Today, when you catch yourself being self-critical about social moments, pause and ask: ''What would I say to a dear friend in this situation?'' Offer yourself that same kindness and understanding.', 'awareness');
INSERT INTO public.suggestions VALUES ('27a93f08-71c6-4fdd-a909-ad6aca8489be', 1, 7, 'Celebration Ritual', 'You''ve completed your first week of awareness building! Create a meaningful way to celebrate this milestone - perhaps a favorite treat, a special activity, or simply a quiet moment to acknowledge your courage and growth.', 'awareness');
INSERT INTO public.suggestions VALUES ('0ec07212-14ec-45f2-83ec-7372dd18548d', 2, 1, 'Smile at Yourself', 'Find a quiet moment today to look at yourself in the mirror and offer yourself a genuine, warm smile for 30 seconds. Notice how this simple act of self-kindness feels and how it might shift your mood.', 'comfort');
INSERT INTO public.suggestions VALUES ('7deba3cb-6d69-49ae-abc9-ebcc29a9c316', 2, 2, 'Eye Contact with Cashiers', 'When you interact with cashiers or service workers today, practice making brief, friendly eye contact. Even just a moment of genuine human connection can feel meaningful for both of you.', 'comfort');
INSERT INTO public.suggestions VALUES ('7608bcd8-49a3-47d1-a27c-03a3bcb75d39', 2, 3, 'Thank You Practice', 'Today, express heartfelt gratitude to at least 3 people you encounter. Look them in the eyes as you say ''thank you'' and let them feel the genuine appreciation behind your words.', 'comfort');
INSERT INTO public.suggestions VALUES ('8981ef25-8540-4f1f-89f1-094e53384d64', 2, 4, 'Say Excuse Me', 'When you need to pass by someone or gently get their attention today, practice saying ''excuse me'' with a warm, polite tone. Add a moment of friendly eye contact to make the interaction feel more connected.', 'comfort');
INSERT INTO public.suggestions VALUES ('19f59ea1-2914-4bab-9e53-af9160bca2bb', 2, 5, 'Weather Comment', 'Strike up a small conversation today by making a casual, genuine comment about the weather to someone you encounter - perhaps a cashier, neighbor, or coworker. Keep it simple and let it flow naturally.', 'comfort');
INSERT INTO public.suggestions VALUES ('2afba7c5-7e40-42b6-bae7-ece69a99c6cc', 2, 6, 'Compliment Someone', 'Brighten someone''s day by offering a sincere compliment. It might be about something they''re wearing, their helpfulness, or any positive quality you genuinely notice. Let your authentic appreciation shine through.', 'comfort');
INSERT INTO public.suggestions VALUES ('78c0071f-a17d-4b1d-a564-c9b34660d22a', 2, 7, 'Phone Call Practice', 'Choose one moment today where you would normally send a text and make a phone call instead. Whether it''s ordering food, checking store hours, or reaching out to a family member, embrace the warmth of voice-to-voice connection.', 'comfort');
INSERT INTO public.suggestions VALUES ('7b2e21b6-386a-4b96-b924-e5cf036987ca', 3, 1, 'Ask for Help', 'Today, practice the gentle art of asking for help. Reach out to someone for small assistance or directions - even if you already know the answer. Focus on gracefully receiving their kindness and support.', 'interaction');
INSERT INTO public.suggestions VALUES ('29b44a39-4ed9-4249-8a56-23e1dcec8fc8', 3, 2, 'Give a Genuine Compliment', 'Approach someone and give them a heartfelt compliment about something specific you''ve noticed - their work, kindness, or style. Practice both giving and receiving positive interactions.', 'interaction');
INSERT INTO public.suggestions VALUES ('733f5d5b-05bc-4ba7-9092-0df83b8e1895', 3, 3, 'Join a Short Conversation', 'When you find yourself near an ongoing conversation today, listen for a natural moment to add a thoughtful comment or question. Trust your instincts about when it feels right to gently join in.', 'interaction');
INSERT INTO public.suggestions VALUES ('75374918-e4f0-4d01-8580-7824dfddd362', 3, 4, 'Express an Opinion', 'Find a moment in conversation today to share a gentle opinion about something neutral - perhaps the weather, a local event, or a TV show you''ve watched. Let your authentic voice be heard in a comfortable way.', 'interaction');
INSERT INTO public.suggestions VALUES ('46ef1989-944d-425d-a122-9739bf921185', 3, 5, 'Ask Follow-up Questions', 'When someone shares something with you today, show genuine curiosity by asking a thoughtful follow-up question. This beautiful habit shows you''re truly listening and helps conversations flow naturally.', 'interaction');
INSERT INTO public.suggestions VALUES ('f237e8d7-169f-4f9a-8034-6376710ebe4b', 3, 6, 'Share Something Personal', 'Open up a little today by sharing something positive and personal - perhaps a hobby you enjoy, weekend plans, or something that sparks your interest. Let others see a glimpse of who you are beyond small talk.', 'interaction');
INSERT INTO public.suggestions VALUES ('9ffdecda-3ef2-486a-8a84-5119beda4392', 3, 7, 'Initiate a Conversation', 'Take the gentle step of starting a conversation with someone new today. A warm ''How''s your day going?'' or similar genuine question can open the door to meaningful connection.', 'interaction');
INSERT INTO public.suggestions VALUES ('09952c71-f748-41f2-a068-e563a35cf08c', 4, 1, 'Attend a Small Group', 'Today, choose to join a small group activity - whether it''s a work meeting, class, or community event. Challenge yourself to stay present for the entire experience, observing how you feel throughout.', 'group');
INSERT INTO public.suggestions VALUES ('bc514115-bb64-4cde-8260-c2773079c5fc', 4, 2, 'Ask About Someone''s Day', 'Reach out to someone today with genuine curiosity about their experience. Ask ''How has your day been?'' or ''How''s everything going?'' and practice the beautiful art of truly listening to their response.', 'group');
INSERT INTO public.suggestions VALUES ('4149e434-ce5d-411f-a06e-a024198e69ac', 4, 3, 'Agree with Someone', 'When you find yourself nodding along with someone''s words today, take the step to voice your agreement out loud. A simple ''I think that''s a great point'' or ''I completely agree'' can strengthen connections.', 'group');
INSERT INTO public.suggestions VALUES ('33f4844b-8e88-47e5-9126-5b6107eb039b', 4, 4, 'Share a Personal Recommendation', 'Recommend something you genuinely enjoy (book, restaurant, movie, app) to someone who might appreciate it. Practice sharing your preferences with others.', 'interaction');
INSERT INTO public.suggestions VALUES ('11ec9b63-c9fe-4790-9e3e-a6bf91613842', 4, 5, 'Compliment the Group', 'Acknowledge the positive energy or insights in a group setting today. Share something like ''This has been really helpful'' or ''I appreciate how thoughtful everyone is being.'' Your recognition can uplift the entire atmosphere.', 'group');
INSERT INTO public.suggestions VALUES ('bdc74308-e184-4e00-8dda-d503b40fd46e', 4, 6, 'Share a Resource', 'When the moment feels right, offer something valuable to others - perhaps a helpful link, book recommendation, or useful information that relates to your conversation. Sharing your knowledge is a gift to the community.', 'group');
INSERT INTO public.suggestions VALUES ('735e9c1a-5674-44af-b0bb-15f0eafdf76b', 5, 1, 'Share a Challenge', 'Open up to someone you trust today about a challenge you''re currently navigating. Share appropriately and ask for their perspective - you might be surprised by the wisdom and support they offer.', 'connection');
INSERT INTO public.suggestions VALUES ('f34f9191-214d-4bb6-8d18-ce88291dcf80', 5, 2, 'Express Vulnerability', 'Take a courageous step today by sharing something you''re learning or working to improve about yourself. This kind of authentic vulnerability often creates the most meaningful connections with others.', 'connection');
INSERT INTO public.suggestions VALUES ('fd551fc1-1bac-4a4a-9d88-0f718fc58436', 5, 3, 'Ask About Someone''s Interests', 'Discover what lights someone up today by asking about their passions or interests. Listen with your full attention and let your genuine curiosity guide the conversation into deeper territory.', 'connection');
INSERT INTO public.suggestions VALUES ('62fcf009-42a4-4d2c-b32e-717838cd19cb', 5, 4, 'Offer Support', 'When someone shares a difficulty they''re facing, extend your heart by offering specific support. A simple ''I''d be happy to help with that'' or ''Would you like to talk about it?'' can mean the world to someone.', 'connection');
INSERT INTO public.suggestions VALUES ('c98431e5-81eb-4630-acd2-b06725387c71', 5, 5, 'Share a Success', 'Celebrate yourself today by sharing a recent win or accomplishment with someone who cares about you. Practice receiving their positive feedback gracefully and let yourself fully enjoy the moment.', 'connection');
INSERT INTO public.suggestions VALUES ('75358053-3bd5-49e6-8075-82ea889c76d2', 5, 6, 'Make Plans', 'Take the initiative to deepen a budding connection by suggesting specific plans together. Whether it''s coffee, a walk, or attending an event, your invitation shows that you value the relationship.', 'connection');
INSERT INTO public.suggestions VALUES ('b0dc53e7-8784-4316-b472-deeb5721f654', 5, 7, 'Express Appreciation', 'Touch someone''s heart today by telling them specifically how they''ve helped or positively impacted your life. Share the details of what you appreciate - your words might be exactly what they need to hear.', 'connection');
INSERT INTO public.suggestions VALUES ('805127fd-8a8e-48ef-aed4-69ee4b33280a', 6, 1, 'Lead a Conversation', 'Step into your power today by guiding a conversation toward something you''re knowledgeable or passionate about. Trust that your insights and enthusiasm have value and can enrich the discussion.', 'confidence');
INSERT INTO public.suggestions VALUES ('8a129a10-bd9f-4ba0-b041-ef1d87e48f6c', 6, 2, 'Handle Disagreement', 'When you find yourself holding a different viewpoint today, practice expressing it with respect and calm confidence. Remember that healthy disagreement can lead to richer understanding for everyone involved.', 'confidence');
INSERT INTO public.suggestions VALUES ('261f779b-109b-4f82-863b-4722079ec8b6', 6, 3, 'Public Speaking Moment', 'Embrace a moment of visibility today by speaking up in a larger group setting. Whether making an announcement, asking a question in a meeting, or sharing during a presentation, let your voice be heard with confidence.', 'confidence');
INSERT INTO public.suggestions VALUES ('0a1ce99d-85aa-4053-b75d-9e4f85f9c736', 6, 4, 'Network Intentionally', 'Attend a networking event, social gathering, or community meeting today with the intention of making genuine connections with 2-3 new people. Approach each interaction with curiosity and openness.', 'confidence');
INSERT INTO public.suggestions VALUES ('e335a4cc-a73d-46c9-acf8-c0a0acdf0ccd', 6, 5, 'Set a Boundary', 'Honor your needs today by setting a kind but firm boundary when a situation calls for it. Use clear ''I'' statements and speak with gentle directness - this is an act of self-respect.', 'confidence');
INSERT INTO public.suggestions VALUES ('81c98cbb-a32b-421d-8c13-3ea61f3cb9fe', 6, 6, 'Celebrate Your Growth', 'Take a moment to share your incredible journey with someone you trust. Reflect on how much you''ve grown since beginning this program and truly acknowledge the courage and progress you''ve made.', 'confidence');
INSERT INTO public.suggestions VALUES ('f7ee629e-a4d1-4a00-8b1c-8731d610bea5', 6, 7, 'Plan Your Future', 'As you near the completion of this transformative journey, create a thoughtful plan for continuing your social growth. Set 2-3 specific, meaningful goals for the next month that will keep you moving forward with confidence.', 'confidence');
INSERT INTO public.suggestions VALUES ('003a8557-c8f1-4688-ae6f-7664f82a07e5', 4, 7, 'Suggest a Group Activity', 'Today, take a small step toward group connection. This could be as simple as: saying "yes" if someone invites you to join them, mentioning you''d be interested if someone suggests plans, or gently asking "mind if I join?" when you see people you know gathering. You don''t need to organize anything - just practice being open to joining in when opportunities arise naturally.', 'group');
INSERT INTO public.user_reflections VALUES ('d036bfee-6adc-4121-845b-3f57adbcb141', '86db7a4f-b6a6-4149-963a-988b3c45252b', '27a93f08-71c6-4fdd-a909-ad6aca8489be', 'nknk', 'You''re building confidence like a coral reef - slowly but surely, creating something strong and beautiful. 🐚🌊', 'positive', true, '2025-09-23 17:41:34.178519');
INSERT INTO public.user_reflections VALUES ('c5ad7016-e233-4f88-945f-3d12d73f3966', 'c640e317-5205-4933-a5dd-4c2ce7071922', 'b7d866de-9ba9-454f-8c19-c0c94e8c4e57', 'whisk', 'Like a crab slowly emerging from its shell, you''re discovering your own strength. Keep going! 🦀🌊', 'positive', true, '2025-09-23 17:40:03.394103');
INSERT INTO public.user_reflections VALUES ('9c482fe0-f3fd-41b3-84de-7dd23abfa358', '86db7a4f-b6a6-4149-963a-988b3c45252b', 'b7d866de-9ba9-454f-8c19-c0c94e8c4e57', 'okay', 'Each challenge you face is like a shell being polished by the waves - you''re becoming more beautiful with every experience. 🐚⭐', 'positive', true, '2025-09-23 17:40:42.470515');
