INSERT INTO public.user_reflections VALUES ('13fe1fed-7f3b-4931-a16e-1666826e800a', 'b5f80c97-89b6-42e0-954e-e70543e6f5af', 'b7d866de-9ba9-454f-8c19-c0c94e8c4e57', 'Tried the breathing exercise today. I noticed my breathing quickened around others but focusing on it helped a bit.', 'Like a crab slowly emerging from its shell, you''re discovering your own strength. Keep going! 🦀🌊', 'positive', true, '2025-09-23 17:41:00.735053');
