INSERT INTO public.user_reflections VALUES ('48f451e2-b769-4891-9cc2-a97ba639b8f1', '05ba6676-e772-45fe-b477-3d02c55133f1', '33f4844b-8e88-47e5-9126-5b6107eb039b', 'a', 'I see the courage in your action, and I''m truly impressed. Sharing your personal preferences is like a sailor unfurling their sails to embrace the sea''s vastness. 🐚 Every time you open up, it''s as though you''re riding a wave, moving steadily towards calmer waters. 🌊 Your willingness to step into this tide shows your growth and resilience, much like a lighthouse standing firm amidst the storm. As you continue on this journey, remember that each small act of sharing is a beacon guiding you towards greater connection and confidence. 🌟🦀', 'positive', true, '2025-12-11 20:33:25.387962');
INSERT INTO public.user_reflections VALUES ('38524fb6-286e-4da0-8cee-a85ca01b7542', '8a15f3b4-35a3-4810-beb5-85c298d0633b', 'b94a76ec-7d46-4e55-bb82-3db917e34f51', 'a', 'Ahoy, brave sailor of the social seas! 🌊 Your willingness to steer into the current of self-awareness is as courageous as navigating stormy waters. Each moment spent relaxing your shoulders or unclenching your jaw is like a gentle tide lapping against a peaceful shore. 🐚⚓ Just as every ocean wave is unique, so too is your journey. Remember, whether you''re nestled in a calm bay or venturing into the vast open sea, your feelings are your true compass. Stay anchored in your own strength, and know I''m here to support you as you chart your course through these social waters. 🦀⭐🐟', 'encouraging', true, '2025-12-11 20:39:02.093572');
